import json
import re
from pathlib import Path

HERE = Path(__file__).resolve().parent
REPO = HERE.parents[3]

P = lambda s: {'type': 'p', 'text': s}
H2 = lambda s: {'type': 'h2', 'text': s}
H3 = lambda s: {'type': 'h3', 'text': s}
N = lambda s: {'type': 'note', 'text': s}
Q = lambda s: {'type': 'formula', 'text': s}
B = lambda *items: {'type': 'bullets', 'items': list(items)}
CODE = lambda s: {'type': 'code', 'text': s}
F = lambda key, f, c, width=565: {'type': 'figure', 'key': key, 'file': 'figures/' + f + '.png', 'caption': c, 'width': width}


def T(key, caption, headers, rows, widths=None):
    return dict(type='table', key=key, caption=caption, headers=headers, rows=rows, widths=widths or [1] * len(headers))


