# ---------------------------------------------------------------- 부록: excerpts read from the repository
def between(path, start, end=None, *, lines=None, after=None):
    text = (REPO / path).read_text()
    if lines:
        return '\n'.join(text.splitlines()[lines[0] - 1:lines[1]])
    i = text.index(start, text.index(after) if after else 0)
    j = text.index(end, i) if end else len(text)
    return text[i:j].rstrip()


