# ---------------------------------------------------------------- resolve citations, tables, figures
cite_order = []


def cite(m):
    keys = m.group(1).split(',')
    for k in keys:
        if k not in REFS:
            raise KeyError(k)
        if k not in cite_order:
            cite_order.append(k)
    nums = sorted(cite_order.index(k) + 1 for k in keys)
    return '[' + ','.join(map(str, nums)) + ']'


def texts(block):
    if block['type'] == 'table':
        yield 'caption', None
        for i, h in enumerate(block['headers']):
            yield 'headers', i
        for r, row in enumerate(block['rows']):
            for c, _ in enumerate(row):
                yield 'rows', (r, c)
    elif block['type'] == 'bullets':
        for i, _ in enumerate(block['items']):
            yield 'items', i
    elif 'text' in block:
        yield 'text', None
    if block['type'] == 'figure':
        yield 'caption', None


def rewrite(block, fn):
    for field, idx in texts(block):
        if idx is None:
            block[field] = fn(block[field])
        elif isinstance(idx, tuple):
            block[field][idx[0]][idx[1]] = fn(block[field][idx[0]][idx[1]])
        else:
            block[field][idx] = fn(block[field][idx])


# Korean particle after a number: 은/이/과/을 if the number's reading ends in a final consonant (0 1 3 6 7 8), else 는/가/와/를.
PAIRS = {'은': '는', '이': '가', '과': '와', '을': '를'}
PAIRS.update({v: k for k, v in PAIRS.items()})


def josa(num, particle):
    if not particle:
        return ''
    closed = str(num)[-1] in '013678'
    pair = {particle, PAIRS[particle]}
    return next(x for x in pair if (x in '은이과을') == closed)


tables, figures = {}, {}
for s in sections:
    for b in s['blocks']:
        if b['type'] == 'table':
            tables[b['key']] = len(tables) + 1
            b['caption'] = f"표 {tables[b['key']]}. " + b['caption']
        if b['type'] == 'figure':
            figures[b['key']] = len(figures) + 1
            b['caption'] = f"그림 {figures[b['key']]}. " + b['caption']
for s in sections:
    for b in s['blocks']:
        if b['type'] == 'code':
            continue
        rewrite(b, lambda t: re.sub(r'\{c:([a-z0-9_,]+)\}', cite, t))
        rewrite(b, lambda t: re.sub(r'\{t:(\w+)\}(?:(은|는|이|가|과|와|을|를)(?![가-힣]))?',
                                    lambda m: f'표 {tables[m.group(1)]}' + josa(tables[m.group(1)], m.group(2)), t))
        rewrite(b, lambda t: re.sub(r'\{f:(\w+)\}(?:(은|는|이|가|과|와|을|를)(?![가-힣]))?',
                                    lambda m: f'그림 {figures[m.group(1)]}' + josa(figures[m.group(1)], m.group(2)), t))
        rewrite(b, lambda t: re.sub(r'\{([A-Z0-9_]+)\}', lambda m: COUNTS[m.group(1)], t))
unused = set(REFS) - set(cite_order)
if unused:
    raise SystemExit(f'uncited references: {sorted(unused)}')
refs = [dict(type='ref', n=i + 1, text=REFS[k]) for i, k in enumerate(cite_order)]
appendix = sections.pop()
sections.append(dict(title='■ 참고문헌', newpage=True, blocks=refs))
sections.append(appendix)

out = dict(title='GPU 프로파일링·시뮬레이션 기반 LLM 추론 attention 커널 동적 선택 시스템', sections=sections)
